# Second-moment triple series Z(s1,s2,w) = sum_m psi(m^3,s1) conj psi(m^3,s2) N(m)^-w, centred coords u = (s1-1/2, s2-1/2, w-1/2).
# FEs: sigma_i(u)_j = u_j - c(j,i) u_i with c(1,3)=c(2,3)=-1 (L(w) conductor N(c1 c2)), c(3,1)=c(3,2)=-3 (Kubota index m^3), c(1,2)=0.
# Absolute convergence: C0 = rho + {u_i > 0}, rho = (1/2,1/2,1/2).  Bochner region = conv(W.C0) = conv(W.rho) + Tits cone.
# Question: min u3 with (0,0,u3) in conv(W.rho) + X  (X generated by W.e_i).  (L3) needs this <= 1/2.
import numpy as np, itertools
from scipy.optimize import linprog
C={(1,1):2,(2,2):2,(3,3):2,(1,2):0,(2,1):0,(1,3):-1,(2,3):-1,(3,1):-3,(3,2):-3}
S={}
for i in (1,2,3):
    M=np.eye(3)
    for j in (1,2,3): M[j-1,i-1]-=C[(j,i)]
    S[i]=M
# check orders
def order(A):
    P=np.eye(3)
    for k in range(1,40):
        P=P@A
        if np.allclose(P,np.eye(3)): return k
    return None
print("orders s1s2,s1s3,s2s3:",order(S[1]@S[2]),order(S[1]@S[3]),order(S[2]@S[3]))
# enumerate group elements by BFS up to length L
L=int(__import__('sys').argv[1]) if len(__import__('sys').argv)>1 else 14
elems={tuple(np.eye(3).round(9).flatten()):np.eye(3)}; frontier=[np.eye(3)]
for _ in range(L):
    nf=[]
    for g in frontier:
        for i in (1,2,3):
            h=S[i]@g; k=tuple(h.round(6).flatten())
            if k not in elems: elems[k]=h; nf.append(h)
    frontier=nf
G=list(elems.values()); print("group elements up to length",L,":",len(G))
rho=np.array([.5,.5,.5]); E=np.eye(3)
pts=np.array([g@rho for g in G]); rays=np.array([g@E[:,i] for g in G for i in range(3)])
# normalise rays
rays=rays/np.linalg.norm(rays,axis=1)[:,None]
def feasible(target):
    n,m=len(pts),len(rays)
    A_eq=np.hstack([pts.T,rays.T]); A_eq=np.vstack([A_eq,np.hstack([np.ones(n),np.zeros(m)])])
    b_eq=np.concatenate([target,[1]])
    r=linprog(np.zeros(n+m),A_eq=A_eq,b_eq=b_eq,bounds=(0,None),method='highs')
    return r.status==0
lo,hi=-5,5
assert feasible(np.array([0,0,hi]))
for _ in range(40):
    mid=(lo+hi)/2
    if feasible(np.array([0,0,mid])): hi=mid
    else: lo=mid
print("min u3 with (0,0,u3) in conv(W.rho)+X (inner approx): %.6f  -> need <= 0.5 for (L3)"%hi)
